import {
  IonButtons,
  IonContent,
  IonHeader,
  IonMenuButton,
  IonPage,
  IonTitle,
  IonToolbar,
} from '@ionic/react';
import React, { useEffect, useRef, useState } from 'react';
import './Home.css';
import './ResultModal.css';
import backgroundMusicFile from './sound/Comedy Funny Circus Background Music For Videos.mp3';
import correctSoundFile from './sound/mixkit-correct-positive-notification-957.wav';
import wrongSoundFile from './sound/mixkit-funny-giggling-2885.wav';
import { supabase } from '../utils/supabaseClient';

type Question = {
  text: string;
  type: 'good' | 'bad';
  value: number;
  image: string;
};

const getEmojiFromScore = (score: number) => {
  if (score <= -3) return '😈';
  if (score <= -1) return '🙁';
  if (score === 0) return '😐';
  if (score <= 2) return '🙂';
  return '😇';
};

const getRankTitle = (correctAnswers: number) => {
  if (correctAnswers >= 5) return '🕊️ Bootan rakayoka pag na na 😇';
  if (correctAnswers >= 3) return '😇 Malangit ka piro de pa sure ';
  if (correctAnswers >= 1) return '🙂 Pag bag o na palihog ';
  return '😈 Yawaa nimo oi pag bag o na';
};

const Home: React.FC = () => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [score, setScore] = useState(0);
  const [correctPoints, setCorrectPoints] = useState(0);
  const [correctAnswers, setCorrectAnswers] = useState(0);
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [finalDestination, setFinalDestination] = useState('');
  const [gameOver, setGameOver] = useState(false);
  const [timeLeft, setTimeLeft] = useState(10);
  const [loading, setLoading] = useState(true);
  const timerRef = useRef<NodeJS.Timeout | null>(null);
  const [incorrectAnswers, setIncorrectAnswers] = useState(0);
const [resultLoading, setResultLoading] = useState(false);



  const correctSound = useRef(new Audio(correctSoundFile));
  const wrongSound = useRef(new Audio(wrongSoundFile));
  const backgroundMusic = useRef(new Audio(backgroundMusicFile));

  const goodImages = [
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
  ];

  const badImages = [
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
  ];

  const fetchQuestions = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('questions')
      .select('text, type, value');

    if (error) {
      console.error('Error fetching questions:', error.message);
      setLoading(false);
      return;
    }

    if (data) {
      const shuffled = data.sort(() => 0.5 - Math.random()).slice(0, 6);
      const withImages: Question[] = shuffled.map((q) => ({
        ...q,
        image:
          q.type === 'good'
            ? goodImages[Math.floor(Math.random() * goodImages.length)]
            : badImages[Math.floor(Math.random() * badImages.length)],
      }));
      setQuestions(withImages);
    }

    setLoading(false);
  };

  useEffect(() => {
    fetchQuestions();
    backgroundMusic.current.loop = true;
    backgroundMusic.current.play();

    return () => {
      backgroundMusic.current.pause();
    };
  }, []);

  useEffect(() => {
    if (gameOver || questions.length === 0) return;

    setTimeLeft(10);
    if (timerRef.current) clearInterval(timerRef.current);

    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev === 1) {
          clearInterval(timerRef.current!);
          handleAnswer('timeout');
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timerRef.current!);
  }, [currentQuestion]);

  const handleAnswer = (choice: 'yes' | 'no' | 'timeout') => {
  if (timerRef.current) clearInterval(timerRef.current);

  const current = questions[currentQuestion];
  let delta = 0;
  let isCorrect = false;

  const isGoodDecision =
    (current.type === 'good' && choice === 'yes') ||
    (current.type === 'bad' && choice === 'no');

  const isTimeoutBad = choice === 'timeout' && current.type === 'good';

  if (choice === 'timeout') {
    delta = isTimeoutBad ? -Math.abs(current.value) : 0;
  } else {
    delta = isGoodDecision ? current.value : -Math.abs(current.value);
    (isGoodDecision ? correctSound : wrongSound).current.play();
  }

  if (isGoodDecision) isCorrect = true;

  setScore(prev => prev + delta);
  if (isCorrect) {
    setCorrectAnswers(prev => prev + 1);
    setCorrectPoints(prev => prev + current.value);
  } else {
    setIncorrectAnswers(prev => prev + 1);  
  }

  setLoading(true);

 
  setTimeout(() => {
    setResultLoading(true);
    setTimeout(() => {
      if (currentQuestion < questions.length - 1) {
        setCurrentQuestion(q => q + 1);
      } else {
        const destination =
          (correctPoints + (isCorrect ? current.value : 0)) >= 3
            ? 'Langit 😇'
            : 'Impiyerno 🔥';
        setFinalDestination(destination);
        setGameOver(true);
      }
       setResultLoading(false);
      setLoading(false);
    }, 2000); 
  }, 300); 
};


  const resetGame = async () => {
    setScore(0);
    setCorrectAnswers(0);
    setCorrectPoints(0);
    setCurrentQuestion(0);
    setFinalDestination('');
    setGameOver(false);
    await fetchQuestions();
    backgroundMusic.current.play();
  };

  return (



    
    <IonPage>
      <IonHeader>
        <IonToolbar color="dark">
          <IonButtons slot="start">
            <IonMenuButton />
          </IonButtons>
          <IonTitle className="title-glow">Path to Heaven or Hell</IonTitle>
        </IonToolbar>
      </IonHeader>

      <IonContent className="ion-padding">
        <div className="home-container">
          <h1>Heaven or Hell</h1>

          {!gameOver ? (
            <div className="question-container">
              {loading || questions.length === 0 ? (
                <div className="loading-screen">
                  <p>Loading...</p>
                </div>
              ) : (
                <>
                  <div className="avatar">
                    <img
                      src={questions[currentQuestion].image}
                      alt={questions[currentQuestion].type}
                      className="avatar-image"
                    />
                  </div>

                  <p className="question">{questions[currentQuestion].text}</p>

                  <div className="timer">
                    <div className="timer-circle">
                      <svg>
                        <circle cx="30" cy="30" r="28" />
                        <circle
                          cx="30"
                          cy="30"
                          r="28"
                          style={{
                            strokeDashoffset: 176 - (176 * timeLeft) / 10,
                            stroke: timeLeft <= 3 ? 'red' : '#4caf50',
                          }}
                        />
                      </svg>
                      <div className="timer-text">{timeLeft}s</div>
                    </div>
                  </div>

                  <div className="btn-group">
                    <button
                      className="btn good"
                      onClick={() => handleAnswer('yes')}
                    >
                      Yes
                    </button>
                    <button
                      className="btn bad"
                      onClick={() => handleAnswer('no')}
                    >
                      No
                    </button>
                  </div>
                </>
              )}
            </div>
          ) : (
            <div className="result">
              {resultLoading ? (
                <div className="loading-screen">
                  <p>Processing results...</p>
                </div>
              ) : (
                <>
                  <h2>
                    Nakaabot ka sa: <span className="result-text">{finalDestination}</span>
                  </h2>
                  <p>✅ Correct Answers: <strong>{correctAnswers}</strong></p>
                  <p>❌ Incorrect Answers: <strong>{incorrectAnswers}</strong></p>
                  <p>⭐ Correct Answer Points: <strong>{correctPoints}</strong></p>
                  <p>🏅 Guide: <strong>{getRankTitle(correctAnswers)}</strong></p>
                  <p>🎉 Congratulations! You're going to {finalDestination}!</p>
                  <button className="btn reset" onClick={resetGame}>
                    Play Again 🔁
                  </button>
                </>
              )}
            </div>
          )}
        </div>
      </IonContent>
    </IonPage>
  );
};

export default Home;